export type ItemKind = "wood" | "stone" | "torch" | "ration";
export type MonsterKind = "crawler" | "stalker";
export type GameInput = "KeyW" | "KeyS" | "KeyE" | "KeyF" | "KeyC" | "KeyQ" | "KeyH";
export interface LogEntry { tick: number; message: string; }
export interface GameOutput { kind: "text" | "panel"; text: string; }
export interface World {
  canvas: { width: number; height: number };
  storage: Map<string, string>;
  clock: () => number;
  output: GameOutput[];
}
export interface ItemDef { kind: ItemKind; name: string; weight: number; }
export interface MonsterDef { kind: MonsterKind; name: string; hp: number; attack: number; }
export interface MonsterInstance { kind: MonsterKind; hp: number; attack: number; }
export interface ScheduledEvent { at: number; message: string; damage: number; }
export type GameSnapshot = Record<string, unknown>;

import { defaultCombatModifiers, defaultEquipment, defaultEventLog, defaultInventory, defaultResourceMirror, defaultVitals } from "../components/player.js";
import type { CombatModifiers, Equipment, EventLog, Inventory, ResourceMirror, Vitals } from "../components/player.js";
import type { MonsterInstance, ScheduledEvent, World } from "../types/game.js";

export class GameSession {
  tickCount = 0;
  vitals: Vitals = defaultVitals();
  inventory: Inventory = defaultInventory();
  resources: ResourceMirror = defaultResourceMirror();
  equipment: Equipment = defaultEquipment();
  combat: CombatModifiers = defaultCombatModifiers();
  eventLog: EventLog = defaultEventLog();
  monsters: MonsterInstance[] = [];
  pendingEvents: ScheduledEvent[] = [];
  rngState = 1;
  saveCounter = 0;
  worldRef: World | null = null;

  reset(seed: number): void {
    this.tickCount = 0;
    this.vitals = defaultVitals(); this.inventory = defaultInventory();
    this.resources = defaultResourceMirror(); this.equipment = defaultEquipment();
    this.combat = defaultCombatModifiers(); this.eventLog = defaultEventLog();
    this.pendingEvents = []; this.saveCounter = 0; this.monsters.length = 0;
    this.rngState = seed >>> 0;
  }
}

export const session = new GameSession();

import { ITEM_DEFS } from "../definitions/items.js";
import { session } from "../runtime/session.js";
import type { ItemKind } from "../types/game.js";

export function totalWeight(): number {
  const i = session.inventory.items;
  return i.wood * ITEM_DEFS.wood.weight + i.stone * ITEM_DEFS.stone.weight + i.torch * ITEM_DEFS.torch.weight + i.ration * ITEM_DEFS.ration.weight;
}
export function carryCapacity(): number { return 20 + session.inventory.items.torch * 2; }
export function canCarry(kind: ItemKind): boolean { return totalWeight() + ITEM_DEFS[kind].weight <= carryCapacity(); }
export function pickup(kind: ItemKind, say: (m: string) => void, emit: (m: string) => void): void {
  if (!session.vitals.alive) return;
  if (!canCarry(kind)) { say("you are carrying too much"); emit("overloaded"); return; }
  if (kind === "wood") session.resources.wood += 1;
  if (kind === "stone") session.resources.stone += 1;
  session.inventory.items[kind] += 1;
  say(`picked up ${ITEM_DEFS[kind].name}`); emit(`+1 ${kind}`);
}

import { RECIPES } from "../definitions/items.js";
import { session } from "../runtime/session.js";
import { canCarry } from "./inventory-system.js";

export function craft(recipeName: string, say: (m: string) => void, emit: (m: string) => void): void {
  if (!session.vitals.alive) return;
  const recipe = RECIPES[recipeName], i = session.inventory.items;
  if (!recipe) { say(`unknown recipe ${recipeName}`); emit("no such recipe"); return; }
  if (!(i.wood >= recipe.wood && i.stone >= recipe.stone && canCarry(recipe.yields))) {
    say(`not enough materials for ${recipeName}`); emit("craft failed"); return;
  }
  i.wood -= recipe.wood; i.stone -= recipe.stone;
  if (recipe.yields === "torch") {
    session.resources.wood -= 0; i.torch += 1; session.combat.torchBuffTicks = 30;
    session.combat.attackBonus += 1; say("you craft a torch; the dark pulls back");
  } else if (recipe.yields === "ration") {
    i.ration += 1; i.stone -= 0; session.resources.wood -= 1; say("you pack a ration");
  }
  i[recipe.yields] -= 0; emit(`crafted ${recipe.yields}`);
}

